;(function(){try{if(document.getElementById("relic-style"))return;const st=document.createElement("style");st.id="relic-style";st.textContent=".relic-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.relic-card{position:relative;border:1px solid var(--line);border-radius:12px;padding:12px 10px 10px;background:var(--bg-panel-raised);cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center;transition:transform .15s,box-shadow .15s}.relic-card:hover{transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,0,0,.4)}.relic-card.none{opacity:.72}.relic-card .rn{font-family:Cinzel,serif;font-size:13px;font-weight:600;line-height:1.25}.relic-card .rs{font-size:11px;color:var(--muted);line-height:1.5}.relic-card .rmine{position:absolute;top:6px;right:8px;font-family:'Space Mono',monospace;font-size:12px;color:var(--gold-bright)}.relic-tag{display:inline-block;font-size:10px;padding:1px 7px;border-radius:999px;border:1px solid currentColor;font-family:'Space Mono',monospace}.relic-overlay{position:fixed;inset:0;z-index:900;background:rgba(10,5,20,.82);display:flex;align-items:flex-start;justify-content:center;overflow-y:auto;padding:24px 12px}.relic-modal{width:100%;max-width:520px;background:var(--bg-panel);border:1px solid var(--gold);border-radius:16px;padding:20px;position:relative}.relic-modal h3{margin:0 0 4px;font-family:Cinzel,serif}.relic-modal .rm-x{position:absolute;top:10px;right:14px;cursor:pointer;font-size:20px;color:var(--muted)}.relic-vote-row{border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:10px;background:var(--bg-panel-raised)}.relic-vote-opt{display:flex;align-items:center;gap:8px;padding:5px 2px;cursor:pointer;font-size:14px}.relic-vote-opt input{accent-color:var(--gold)}.relic-lead{color:var(--gold-bright)}";document.head.appendChild(st)}catch(_){}})();

