function antGmHtml(){
  const c=(ANT.data&&ANT.data.cfg)||{},inp=(id,v,w)=>`<input type="text" id="${id}" value="${Iu(v==null?"":v)}" style="width:${w||90}px;" />`,bp=c.fallback_prices||c.base_prices||{};
  return`<div class="panel"><details id="ant-gm-details" ${ANT.gmOpen?"open":""}><summary style="cursor:pointer;font-family:Cinzel,serif;color:var(--gold-bright);font-size:16px;">🔍 ${dc("古董鑒定（GM）","Antique Appraisal (GM)")}</summary><p class="who" style="margin-top:8px;">${dc("儲存會呼叫 antique_gm_update_config；你的 GM 暱稱必須先寫進 antique_config 的 gm_nicks（SQL 檔最下面有指令）。分數機率與倍率請直接編輯 antique_config.main.scores。","Saving calls antique_gm_update_config; your GM nickname must be in gm_nicks first (see the bottom of the SQL file). Edit antique_config.main.scores directly to change odds/multipliers.")}</p><div class="form-row"><div><label>${dc("每日免費次數","Free / day")}</label>${inp("ant-gm-free",c.free_appraisals_per_day,60)}</div><div><label>${dc("每 VIP 等級加","+ per VIP")}</label>${inp("ant-gm-vip",c.extra_per_vip_level,60)}</div><div><label>${dc("上榜最低成交價","Min rank price")}</label>${inp("ant-gm-minrank",relicCoinStr(c.min_rank_price),110)}</div></div><div class="form-row">${["common","rare","epic","legendary"].map(t=>{const id=RELIC_CATALOG.find(it=>it.tier===t).id;return`<div><label>${dc("無成交時備用價 ","Fallback price ")}${Iu(relicTierLabel(t))}</label>${inp("ant-gm-bp-"+t,relicCoinStr(bp[id]),110)}</div>`}).join("")}</div><div class="form-row"><div><label>${dc("不開放鑒定的編號（逗號分隔，例如 R10, A10）","Disabled ids (comma separated, e.g. R10, A10)")}</label>${inp("ant-gm-off",(c.disabled_ids||[]).join(", "),260)}</div></div><div class="form-row"><button class="btn small" data-ant-gm-save="1">${dc("儲存","Save")}</button></div></details></div>`}

